commit d40cad32b85186e7d760707c61984d3b6fc422b5
Author: Rob Davies <rmd+git@sanger.ac.uk>
Date:   Fri Jan 29 18:11:31 2021 +0000

    Fix CRAM undefined behaviour warnings

    Fixes various warnings from clang 10.0.1 undefined behaviour
    sanitizer:

     - A "runtime error: applying zero offset to null pointer"
       warning in cram_to_bam() on CRAM slices with no CIGAR
       data.  Fix by always allocating memory when creating a
       slice data structure.  For aligned data this simply moves
       the allocation forward in time.  For unaligned data, the
       allocated memory is not really needed, but it's assumed
       that it is quicker to make one allocation per slice than
       to check for a NULL pointer on every call to cram_to_bam().

     - A "runtime error: applying zero offset to null pointer"
       warning in cram_byte_array_stop_decode_block() when it
       is called before the `out` block has been allocated.
       Fix by moving the calculation of `out_cp`.  Also changes
       the type of some variables to `unsigned char` enabling
       removal of a number of (char *) casts.

     - An integer overflow in the cram_metrics::sz array.
       Entries 9 and 10 had a high multiplier to ensure they would
       never win, as they correspond to reserved method codes.
       Under certain conditions the value in them could build up to
       the point where they overflowed.  The methods are masked
       out elsewhere , so the numbers would not have been used, but
       it did cause an overflow warning.  Fix by changing the
       multiplier to 1, and (in a belt-and-braces approach) setting
       the values for these entries to INT_MAX to ensure they won't be
       chosen.

diff --git a/cram/cram_codecs.c b/cram/cram_codecs.c
index 6a4ee782..0c6cb654 100644
--- a/cram/cram_codecs.c
+++ b/cram/cram_codecs.c
@@ -3494,8 +3494,8 @@ int cram_byte_array_stop_decode_block(cram_slice *slice, cram_codec *c,
                                       int *out_size) {
     cram_block *b;
     cram_block *out = (cram_block *)out_;
-    char *cp, *out_cp, *cp_end;
-    char stop;
+    unsigned char *cp, *cp_end;
+    unsigned char stop;

     b = cram_get_block_by_id(slice, c->u.byte_array_stop.content_id);
     if (!b)
@@ -3503,25 +3503,25 @@ int cram_byte_array_stop_decode_block(cram_slice *slice, cram_codec *c,

     if (b->idx >= b->uncomp_size)
         return -1;
-    cp = (char *)b->data + b->idx;
-    cp_end = (char *)b->data + b->uncomp_size;
-    out_cp = (char *)BLOCK_END(out);
+    cp = b->data + b->idx;
+    cp_end = b->data + b->uncomp_size;

     stop = c->u.byte_array_stop.stop;
     if (cp_end - cp < out->alloc - out->byte) {
+        unsigned char *out_cp = BLOCK_END(out);
         while (cp != cp_end && *cp != stop)
             *out_cp++ = *cp++;
-        BLOCK_SIZE(out) = out_cp - (char *)BLOCK_DATA(out);
+        BLOCK_SIZE(out) = out_cp - BLOCK_DATA(out);
     } else {
-        char *cp_start;
+        unsigned char *cp_start;
         for (cp_start = cp; cp != cp_end && *cp != stop; cp++)
             ;
         BLOCK_APPEND(out, cp_start, cp - cp_start);
         BLOCK_GROW(out, cp - cp_start);
     }

-    *out_size = cp - (char *)(b->data + b->idx);
-    b->idx = cp - (char *)b->data + 1;
+    *out_size = cp - (b->data + b->idx);
+    b->idx = cp - b->data + 1;

     return 0;

diff --git a/cram/cram_io.c b/cram/cram_io.c
index 3a6b04c4..8099a928 100644
--- a/cram/cram_io.c
+++ b/cram/cram_io.c
@@ -2080,7 +2080,7 @@ int cram_compress_block2(cram_fd *fd, cram_slice *s,
                     1.04, // 6  arithpr (O0)
                     1.05, // 7  fqz
                     1.05, // 8  tok3 (rans)
-                    9, 9, // 9,10 reserved
+                    1.00, 1.00, // 9,10 reserved

                     // Paramterised versions of above
                     1.01, // gzip rle
@@ -2124,6 +2124,9 @@ int cram_compress_block2(cram_fd *fd, cram_slice *s,
                         metrics->sz[m] *= 1+(meth_cost[m]-1)/3;
                 } // else cost is ignored

+                // Ensure these are never used
+                metrics->sz[9] = metrics->sz[10] = INT_MAX;
+
                 for (m = 0; m < CRAM_MAX_METHOD; m++) {
                     if ((!metrics->sz[m]) || (!(method & (1u<<m))))
                         continue;
@@ -4395,8 +4398,8 @@ cram_slice *cram_new_slice(enum cram_content_type type, int nrecs) {
     s->block_by_id = NULL;
     s->last_apos = 0;
     if (!(s->crecs = malloc(nrecs * sizeof(cram_record))))  goto err;
-    s->cigar = NULL;
-    s->cigar_alloc = 0;
+    s->cigar_alloc = 1024;
+    if (!(s->cigar = malloc(s->cigar_alloc * sizeof(*s->cigar)))) goto err;
     s->ncigar = 0;

     if (!(s->seqs_blk = cram_new_block(EXTERNAL, 0)))       goto err;
@@ -4499,8 +4502,8 @@ cram_slice *cram_read_slice(cram_fd *fd) {
     }
